#include <algorithm>
#include <sstream>
#include <string>
#include <vector>

std::string diagonalSum(std::vector<int> values) {
    std::sort(values.begin(), values.end(), std::greater<int>());
    std::ostringstream output;
    for (size_t index = 0; index < values.size(); index++) {
        if (index > 0) output << ",";
        output << values[index];
    }
    return output.str();
}
